const body = $input.first().json.body || $input.first().json;

if (body.type === 'url_verification') {
  return [{ json: { valid: false, error: 'URL verification' } }];
}

const event = body.event || body;
const messageText = (event.text || '').trim();
const channelId = event.channel || '';
const messageTs = event.ts || '';

if (event.bot_id || event.subtype === 'bot_message') {
  return [{ json: { valid: false, error: 'Bot message ignorado' } }];
}

// ================== CONFIG DOS TIMES / SQUADS ==================
// Todos os projetos sao team-managed (boards "simple"); por isso o boardId
// e fixo aqui (nao da pra achar por type=scrum).
const CONFIG = {
  boards:   { Growth: 176, Content: 209, Studios: 506, Branding: 573 },
  projects: { Growth: 'GWT', Content: 'CONT', Studios: 'SCC', Branding: 'BRAND' },
  // prefixo do codigo de sprint no summary -> [SM23], [SCC06], [SB32]
  sprintPrefix: { Growth: 'SM', Content: 'SM', Studios: 'SCC', Branding: 'SB' },

  issueTypes: {
    Growth:  { 'Historia de Usuario': '10484', Design: '10530', Texto: '10472', Tarefa: '10477', Video: '10482' },
    Content: { 'Historia de Usuario': '10460', Design: '10473', Texto: '10475', Tarefa: '10458', Video: '10478' },
    // SCC e BRAND (team-managed) so tem tipos genericos: pai = Historia, filha = Tarefa
    Studios:  { 'Historia de Usuario': '10971', Tarefa: '10969' },
    Branding: { 'Historia de Usuario': '11050', Tarefa: '11049' }
  },

  // Growth/Content: roteamento por PALAVRA-CHAVE (skill)
  assignees: {
    Growth: {
      copy:   '712020:ea09c087-43cc-4fc9-a933-a0ee84fa2a20',
      design: '712020:cde30452-7b4a-4c2e-8157-db30922c0784',
      lp:     '712020:8f3294aa-7c87-46d8-bd1d-036d306a1270',
      outros: '712020:f2a70006-3b35-49fb-8944-bcbd7887b32f'
    },
    Content: {
      copy:   '712020:6791d341-e96a-43f0-a03b-60ff583aee6e',
      laysla: '712020:73a4ce85-f63a-4b8a-b623-fd368eb1a36b',
      filipe: '712020:e74dc53a-6c5b-42b4-a850-eb9f3910e962',
      video:  '712020:543f11c1-c412-40dd-9ece-174ed0dd3e44'
    }
  },

  // Studios/Branding: roteamento por NOME citado na atividade (variacoes lowercase, sem acento)
  squadMembers: {
    Studios: [
      { accountId: '712020:c4f6e3b2-45e8-4ff9-90c5-c0ebd69e2455', names: ['augusto', 'martelo'] },                       // Augusto Martelo
      { accountId: '712020:25695784-d35b-4697-9e8b-17e132241848', names: ['daniel', 'oliveira'] },                       // Daniel Da Silva Oliveira
      { accountId: '712020:543f11c1-c412-40dd-9ece-174ed0dd3e44', names: ['fabiano', 'bessa', 'diogenes', 'junior'] }    // Fabiano Junior Diogenes Carneiro Bessa
    ],
    Branding: [
      { accountId: '712020:3618017a-f9d6-4b65-ae3a-066e8d014106', names: ['maria eduarda', 'eduarda', 'maria', 'meryl', 'duda'] } // Maria Eduarda Costa da Silva
    ]
  },
  // fallback quando nenhum nome bate
  squadDefault: {
    Studios:  null,                                              // deixa sem responsavel (triagem)
    Branding: '712020:3618017a-f9d6-4b65-ae3a-066e8d014106'      // squad de 1 pessoa -> sempre ela
  },

  linkTypeId: '10006'
};

// aliases digitados no Slack -> nome canonico do time
const TEAM_ALIASES = {
  'growth': 'Growth',
  'content': 'Content', 'conteudo': 'Content',
  'studios': 'Studios', 'cw studios': 'Studios', 'cwstudios': 'Studios', 'scc': 'Studios',
  'branding': 'Branding', 'brand': 'Branding', 'marca': 'Branding'
};

function norm(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
}

function isNameRouted(team) {
  return !!CONFIG.squadMembers[team];
}

function getIssueType(team, taskName) {
  const types = CONFIG.issueTypes[team];
  if (isNameRouted(team)) return types.Tarefa;   // Studios/Branding: filha sempre = Tarefa
  const l = norm(taskName);
  if (/design|layout|banner|criativo/.test(l)) return types.Design;
  if (/video/.test(l)) return types.Video;
  if (/copy|texto|e.?mail/.test(l)) return types.Texto;
  return types.Tarefa;
}

function getAssignee(team, taskName) {
  const l = norm(taskName);
  if (isNameRouted(team)) {
    for (const m of CONFIG.squadMembers[team]) {
      if (m.names.some(n => l.includes(n))) return m.accountId;
    }
    return CONFIG.squadDefault[team];
  }
  if (team === 'Growth') {
    if (/design|layout|banner|criativo/.test(l)) return CONFIG.assignees.Growth.design;
    if (/copy|texto|e.?mail/.test(l)) return CONFIG.assignees.Growth.copy;
    if (/lp|landing|automac|fluxo|disparo/.test(l)) return CONFIG.assignees.Growth.lp;
    return CONFIG.assignees.Growth.outros;
  }
  if (team === 'Content') {
    if (/video/.test(l)) return CONFIG.assignees.Content.video;
    if (/copy|texto/.test(l)) return CONFIG.assignees.Content.copy;
    if (/filipe/.test(l)) return CONFIG.assignees.Content.filipe;
    if (/design|layout/.test(l)) return CONFIG.assignees.Content.laysla;
    return null;
  }
  return null;
}

// 1a coisa da mensagem = time. Ex: "CW Studios - ...", "Branding - ...", "Growth - ..."
const aliasKeys = Object.keys(TEAM_ALIASES).sort((a, b) => b.length - a.length);
const teamPattern = new RegExp('^(' + aliasKeys.join('|') + ')\\s*-\\s*', 'i');

const teamMatch = messageText.match(teamPattern);
if (!teamMatch) {
  return [{ json: { valid: false, error: 'Formato invalido. Use: <Time> - Nome da Atividade', originalText: messageText, channelId, messageTs } }];
}

const team = TEAM_ALIASES[norm(teamMatch[1])];
const afterTeam = messageText.slice(teamMatch[0].length).trim();
const cleanAfterTeam = afterTeam.replace(/\[?\s*(sm|scc|sb)\s*\d+\s*\]?\s*/i, '').trim();

const dashIdx = cleanAfterTeam.indexOf(' - ');
const activityName = dashIdx !== -1 ? cleanAfterTeam.slice(0, dashIdx).trim() : cleanAfterTeam.trim();
const subtasksRaw = dashIdx !== -1 ? cleanAfterTeam.slice(dashIdx + 3).trim() : null;
const project = CONFIG.projects[team];
const boardId = CONFIG.boards[team];

const subtasks = subtasksRaw
  ? subtasksRaw.split(',').map(s => s.trim()).filter(Boolean).map(st => {
      const cleanSt = st.replace(/\s*\(.*?\)/g, '').trim();
      return {
        description: st,
        issueTypeId: getIssueType(team, cleanSt),
        assigneeId:  getAssignee(team, st)
      };
    })
  : [{
      description: activityName,
      issueTypeId: CONFIG.issueTypes[team].Tarefa,
      assigneeId:  isNameRouted(team)
        ? getAssignee(team, activityName)
        : (team === 'Growth' ? CONFIG.assignees.Growth.outros : null)
    }];

return [{
  json: {
    valid: true,
    team,
    project,
    boardId,
    activityName,
    parentIssueTypeId: CONFIG.issueTypes[team]['Historia de Usuario'],
    sprintPrefix: CONFIG.sprintPrefix[team],
    subtasks,
    channelId,
    messageTs,
    linkTypeId: CONFIG.linkTypeId,
    jiraBase: 'https://cardapio-web.atlassian.net'
  }
}];

const input = $input.first().json;
const errorMsg = input.error || 'Erro desconhecido ao processar a mensagem.';
const originalText = input.originalText || '';
const channelId = input.channelId || '';

const message = ':x: *Nao consegui processar sua mensagem.*

Motivo: ' + errorMsg +
  '

Mensagem recebida:
> ' + originalText +
  '

Formato esperado:
> <Time> - Nome da Atividade
> <Time> - Nome - Subtarefa1, Subtarefa2' +
  '

Times disponiveis: Growth, Content, CW Studios, Branding';

return [{ json: { slackMessage: message, channelId } }];

const sprintData = $input.first().json;
const parsed = $('Parser - Extrair Dados da Mensagem').first().json;
const prefix = parsed.sprintPrefix || 'SM';

// pode nao haver sprint ativa (ex: squad entre sprints) -> cria sem sprint (backlog)
const sv = (sprintData.values && sprintData.values.length) ? sprintData.values[0] : null;

let sprintId = null;
let sprintCode = '';
if (sv) {
  const nums = String(sv.name).match(/\d+/g);          // pega todos os numeros do nome da sprint
  const sprintNum = nums ? nums[nums.length - 1] : '00'; // usa o ultimo (funciona p/ "SCC 06", "Sprint SB32", "Sprint Marketing 23")
  sprintCode = '[' + prefix + sprintNum + ']';
  sprintId = sv.id;
}

const codePart = sprintCode ? sprintCode + ' ' : '';

return [{
  json: {
    ...parsed,
    sprintCode,
    sprintId,
    fullName: codePart + parsed.activityName,
    subtasks: parsed.subtasks.map(st => ({
      ...st,
      summary: codePart + parsed.activityName + ' - ' + st.description
    }))
  }
}];

const sprint    = $('Sprint Extraida').first().json;
const parentKey = $('Criar Historia de Usuario').first().json.key;

return sprint.subtasks.map(st => ({
  json: {
    summary:     st.summary,
    issueTypeId: st.issueTypeId,
    assigneeId:  st.assigneeId,
    project:     sprint.project,
    sprintId:    sprint.sprintId,
    parentKey:   parentKey,
    channelId:   sprint.channelId,
    messageTs:   sprint.messageTs,
    fullName:    sprint.fullName,
    jiraBase:    sprint.jiraBase
  }
}));

const parser    = $('Parser - Extrair Dados da Mensagem').first().json;
const sprint    = $('Sprint Extraida').first().json;
const parentKey = $('Criar Historia de Usuario').first().json.key;
const jiraBase  = 'https://cardapio-web.atlassian.net/browse';

const childItems = $('Criar Issue Filha').all().map(item => {
  const key     = item.json.key;
  const summary = (item.json.fields && item.json.fields.summary) ? item.json.fields.summary : '';
  return '  :arrow_right: <' + jiraBase + '/' + key + '|' + key + '> - ' + summary;
}).join('\n');

const message = ':white_check_mark: Atividades criadas para *' + sprint.fullName + '*!\n\n:clipboard: *Historia de Usuario:* <' + jiraBase + '/' + parentKey + '|' + parentKey + '>\n' + childItems;

return [{ json: { slackMessage: message, channelId: parser.channelId } }];
